import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.D7WGirly.js";const u=JSON.parse('{"title":"Goals & Objectives — Advanced & Customization","description":"","frontmatter":{},"headers":[],"relativePath":"goals-03-advanced-and-customization.md","filePath":"goals-03-advanced-and-customization.md"}'),i={name:"goals-03-advanced-and-customization.md"};function s(r,e,l,h,d,c){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="goals-objectives-—-advanced-customization" tabindex="-1">Goals &amp; Objectives — Advanced &amp; Customization <a class="header-anchor" href="#goals-objectives-—-advanced-customization" aria-label="Permalink to &quot;Goals &amp; Objectives — Advanced &amp; Customization&quot;">​</a></h1><p><em>How the top-tier type powers Goals, downstream connection mechanics, and deletion behavior</em></p><hr><h2 id="goals-and-the-top-tier-type" tabindex="-1">Goals and the Top-Tier Type <a class="header-anchor" href="#goals-and-the-top-tier-type" aria-label="Permalink to &quot;Goals and the Top-Tier Type&quot;">​</a></h2><p>Goals are not a separate data model — they are your organization&#39;s <strong>top-tier object type</strong>, surfaced through a dedicated module. The top-tier type is designated in Settings &gt; Taxonomy and represents the highest level of your object hierarchy.</p><p>This design means:</p><ul><li>The same object that appears in Goals &amp; Objectives is the one you can set as a parent on Backlog items</li><li>Goals inherit whatever prefix you&#39;ve configured for your top-tier type (e.g. GOAL-001, OBJ-003)</li><li>Renaming your top-tier type in Taxonomy renames how Goals appear across the platform</li></ul><p>If your organization has not yet designated a top-tier type, Goals will be created without typed IDs. You can configure this at any time in Settings &gt; Taxonomy — existing Goals will receive typed IDs automatically once a top-tier type is set.</p><blockquote><p><strong>Note:</strong> The Goals &amp; Objectives module shows only objects of the top-tier type. Other object types (Features, Epics, etc.) do not appear here, even if they have been given the same name as your goal.</p></blockquote><hr><h2 id="how-downstream-connections-form" tabindex="-1">How Downstream Connections Form <a class="header-anchor" href="#how-downstream-connections-form" aria-label="Permalink to &quot;How Downstream Connections Form&quot;">​</a></h2><p>The downstream view on a Goal is derived automatically from relationships in other modules — there is no manual &quot;connect to goal&quot; action in Roadmaps or Releases.</p><table tabindex="0"><thead><tr><th>Connection type</th><th>How it forms</th></tr></thead><tbody><tr><td><strong>Objects</strong></td><td>You add the Goal as a parent of a Backlog object from that object&#39;s detail page</td></tr><tr><td><strong>Roadmaps</strong></td><td>A Roadmap contains an object that has the Goal as a parent</td></tr><tr><td><strong>Releases</strong></td><td>A Release contains an object that has the Goal as a parent</td></tr><tr><td><strong>Strategies</strong></td><td>A bottom-up Strategy includes objects tagged in a way that maps to the Goal&#39;s child objects</td></tr></tbody></table><p>Connections update in real time. If you remove a Goal as a parent from an object, the Roadmap and Release connections that relied on that relationship disappear from the downstream view as well.</p><hr><h2 id="goals-as-organizing-anchors-not-containers" tabindex="-1">Goals as Organizing Anchors, Not Containers <a class="header-anchor" href="#goals-as-organizing-anchors-not-containers" aria-label="Permalink to &quot;Goals as Organizing Anchors, Not Containers&quot;">​</a></h2><p>Goals in Lodestone are reference points, not containers that own their children exclusively. An object can have multiple parents — including both a Goal and another object — without conflict. Similarly, the same object can contribute to multiple Goals if it is linked to more than one Goal as a parent.</p><p>This is useful when a Feature or Epic genuinely supports multiple strategic objectives. Rather than duplicating the object or choosing one Goal, you can link it to both.</p><hr><h2 id="deletion-and-orphan-behavior" tabindex="-1">Deletion and Orphan Behavior <a class="header-anchor" href="#deletion-and-orphan-behavior" aria-label="Permalink to &quot;Deletion and Orphan Behavior&quot;">​</a></h2><p>When you delete a Goal, child objects are orphaned rather than deleted. Orphaned objects:</p><ul><li>Remain in the Backlog as top-level items</li><li>Lose their parent connection to the deleted Goal</li><li>Retain all other data (name, description, status, documents, quotes)</li><li>Retain any other parent connections they had to non-Goal objects</li></ul><p>The delete confirmation dialog shows you how many objects will be orphaned, grouped by type (e.g. &quot;3 Features, 1 Epic&quot;), so you can decide whether to reassign them before deleting.</p><p>There is no undo for Goal deletion.</p><hr><h2 id="using-goals-with-the-extracts-ai-suggestion" tabindex="-1">Using Goals with the Extracts AI Suggestion <a class="header-anchor" href="#using-goals-with-the-extracts-ai-suggestion" aria-label="Permalink to &quot;Using Goals with the Extracts AI Suggestion&quot;">​</a></h2><p>When adding Extracts to the Backlog, Lodestone&#39;s AI can suggest a Goal to link the new object to. This happens automatically when the AI detects that the Extract&#39;s content semantically matches an existing Goal. The suggestion appears in the Add to Backlog dialog as &quot;✦ AI matched parent goal: [Goal name]&quot; and is pre-populated in the Goal selector.</p><p>You can accept the suggestion, choose a different Goal, or leave the Goal field empty. This is not a required step.</p><p>See the Extracts how-tos guide for more detail on the Add to Backlog flow.</p><hr><p><em>Next: Troubleshooting &amp; FAQs — common questions about the Goals module.</em></p>',31)])])}const m=t(i,[["render",s]]);export{u as __pageData,m as default};
